import{_ as o,o as r,c as a,ae as i}from"./chunks/framework.BzQXgbNp.js";const b=JSON.parse('{"title":"Interface: InvitedUser","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/shared-core/interfaces/InvitedUser.md","filePath":"api-reference/shared-core/interfaces/InvitedUser.md"}'),t={name:"api-reference/shared-core/interfaces/InvitedUser.md"};function d(n,e,s,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<p><a href="./../"><strong>shared-core</strong></a></p><hr><p><a href="./../">shared-core</a> / InvitedUser</p><h1 id="interface-inviteduser" tabindex="-1">Interface: InvitedUser <a class="header-anchor" href="#interface-inviteduser" aria-label="Permalink to &quot;Interface: InvitedUser&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L7" target="_blank" rel="noreferrer">models/invited-user.model.ts:7</a></p><p>InvitedUser</p><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>Modelo estructural para los documentos de la colección <code>/invitedUsers</code>. Actúa como un token de pre-alta o &quot;cerrojo de invitación&quot;. Ningún usuario externo puede completar su registro en la plataforma si su correo electrónico no ha sido sembrado previamente en esta colección por la directiva.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="email" tabindex="-1">email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;email&quot;">​</a></h3><blockquote><p><strong>email</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L19" target="_blank" rel="noreferrer">models/invited-user.model.ts:19</a></p><h4 id="description-1" tabindex="-1">Description <a class="header-anchor" href="#description-1" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Correo electrónico unívoco autorizado para el onboarding.</p><hr><h3 id="fechainvitacion" tabindex="-1">fechaInvitacion <a class="header-anchor" href="#fechainvitacion" aria-label="Permalink to &quot;fechaInvitacion&quot;">​</a></h3><blockquote><p><strong>fechaInvitacion</strong>: <code>string</code> | <code>Date</code> | { <code>nanoseconds</code>: <code>number</code>; <code>seconds</code>: <code>number</code>; }</p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L37" target="_blank" rel="noreferrer">models/invited-user.model.ts:37</a></p><h4 id="description-2" tabindex="-1">Description <a class="header-anchor" href="#description-2" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Fecha y hora exacta de expedición del token de invitación. Soporta Date nativo, String ISO o el mapa estructural Timestamp de Firebase.</p><hr><h3 id="fecharegistro" tabindex="-1">fechaRegistro? <a class="header-anchor" href="#fecharegistro" aria-label="Permalink to &quot;fechaRegistro?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>fechaRegistro?</strong>: <code>string</code> | <code>Date</code> | { <code>nanoseconds</code>: <code>number</code>; <code>seconds</code>: <code>number</code>; }</p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L52" target="_blank" rel="noreferrer">models/invited-user.model.ts:52</a></p><h4 id="description-3" tabindex="-1">Description <a class="header-anchor" href="#description-3" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Fecha y hora en la que el usuario consolidó su onboarding en la app. Soporta Date nativo, String ISO o el mapa estructural Timestamp de Firebase.</p><hr><h3 id="id" tabindex="-1">id? <a class="header-anchor" href="#id" aria-label="Permalink to &quot;id?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>id?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L9" target="_blank" rel="noreferrer">models/invited-user.model.ts:9</a></p><h4 id="description-4" tabindex="-1">Description <a class="header-anchor" href="#description-4" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>ID único autogenerado del documento en Firestore (coincide habitualmente con el email o un UUID).</p><hr><h3 id="invitadopor" tabindex="-1">invitadoPor <a class="header-anchor" href="#invitadopor" aria-label="Permalink to &quot;invitadoPor&quot;">​</a></h3><blockquote><p><strong>invitadoPor</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L29" target="_blank" rel="noreferrer">models/invited-user.model.ts:29</a></p><h4 id="description-5" tabindex="-1">Description <a class="header-anchor" href="#description-5" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Nombre del miembro de la Junta Directiva o Administrador que emite la invitación.</p><hr><h3 id="invitadoporuid" tabindex="-1">invitadoPorUid <a class="header-anchor" href="#invitadoporuid" aria-label="Permalink to &quot;invitadoPorUid&quot;">​</a></h3><blockquote><p><strong>invitadoPorUid</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L32" target="_blank" rel="noreferrer">models/invited-user.model.ts:32</a></p><h4 id="description-6" tabindex="-1">Description <a class="header-anchor" href="#description-6" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>UID físico en Firebase Auth del directivo responsable de la emisión.</p><hr><h3 id="nombre" tabindex="-1">nombre <a class="header-anchor" href="#nombre" aria-label="Permalink to &quot;nombre&quot;">​</a></h3><blockquote><p><strong>nombre</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L16" target="_blank" rel="noreferrer">models/invited-user.model.ts:16</a></p><h4 id="description-7" tabindex="-1">Description <a class="header-anchor" href="#description-7" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Nombre completo del usuario invitado.</p><hr><h3 id="telefono" tabindex="-1">telefono? <a class="header-anchor" href="#telefono" aria-label="Permalink to &quot;telefono?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>telefono?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L22" target="_blank" rel="noreferrer">models/invited-user.model.ts:22</a></p><h4 id="description-8" tabindex="-1">Description <a class="header-anchor" href="#description-8" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Teléfono de contacto opcional del aspirante.</p><hr><h3 id="usado" tabindex="-1">usado <a class="header-anchor" href="#usado" aria-label="Permalink to &quot;usado&quot;">​</a></h3><blockquote><p><strong>usado</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L44" target="_blank" rel="noreferrer">models/invited-user.model.ts:44</a></p><h4 id="description-9" tabindex="-1">Description <a class="header-anchor" href="#description-9" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Flag lógico; true si el aspirante ya ha consumido este token para completar su registro.</p><hr><h3 id="usadoporuid" tabindex="-1">usadoPorUid? <a class="header-anchor" href="#usadoporuid" aria-label="Permalink to &quot;usadoPorUid?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>usadoPorUid?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/models/invited-user.model.ts#L47" target="_blank" rel="noreferrer">models/invited-user.model.ts:47</a></p><h4 id="description-10" tabindex="-1">Description <a class="header-anchor" href="#description-10" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>UID asignado definitivamente al nuevo usuario en Firebase Auth tras canjear la invitación.</p>',68)])])}const u=o(t,[["render",d]]);export{b as __pageData,u as default};
